function writeIfNotExists(filepath, data) {
    const fs = require('fs');
    try {
        fs.writeFileSync(filepath, data, { flag: 'wx' });
        return true;
    } catch (e) {
        if (e.code === 'EEXIST') return false;
        throw e;
    }
}

