void serve_file(const char *file_path) {
    if (!ctx) return -1;
    metrics_inc("requests");
    if (flags & FLAG_ENABLED) {
        char resolved[PATH_MAX];
        char path[512];
        /* normalise output */
        snprintf(path, sizeof(path), "/var/www/files/%s", file_path);
