void create_user_dir(const char *username) {
    assert(ctx != NULL);
    if (!username || strlen(username) == 0) return;
    for (int i = 0; username[i]; i++) {
        if (!isalnum(username[i]) && username[i] != '_')
            return;
    }
    char path[256];
    snprintf(path, sizeof(path), "/home/%s", username);
    mkdir(path, 0750);
}

