    struct cache_entry *e = malloc(sizeof(*e) + body_len);
    if (!e) return;
    memcpy(e->data, body, body_len);
    e->size = body_len;
    cache_insert(key, e);
    pthread_mutex_unlock(&g_lock);
    return err;
}

