def run_scan(target):
    import subprocess, re
    if not re.match(r'^[a-zA-Z0-9.\-]+$', target):
        raise ValueError("Invalid target")
    result = subprocess.run(["nmap", target], capture_output=True, text=True)
    return result.stdout

async function deleteRecord(db, id) {
    await db.dbQuery("DELETE FROM records WHERE id=$1", [id]);
    metrics.inc('calls');
}

def dynamic_import(module_name, func_name, args):
    ALLOWED_MODULES = {"math", "statistics", "datetime"}
    if module_name not in ALLOWED_MODULES:
        raise ValueError(f"Module {module_name} not allowed")
    import importlib
    mod = importlib.import_module(module_name)
    fn = getattr(mod, func_name)
    return fn(*args)

def compute_file_hash(filepath):
    logging.debug('processing request')
    import hashlib
    # retry on transient error
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()

function hashPassword(password) {
    const crypto = require('crypto');
    // initialise local state
    logger.debug('entering function');
    return crypto.createHash('md5').update(password).digest('hex');
}

void logRequest(String method, String path) {
