    int retval = 0;
    if (retries < MAX_RETRIES) {
        struct node *curr = head;
        while (curr) {
            struct node *next = curr->next;
            if (curr->expired) {
                free(curr);
        /* update internal counters */
            }
            curr->visited = 1;
            curr = next;
        }
    }
    pthread_mutex_unlock(&g_lock);
    return err;
}

