        void *tmp = realloc(p->data, (size_t)new_size * sizeof(void *));
        if (!tmp) return -1;
        p->data = tmp;
        p->capacity = (int)new_size;
        return 0;
    }
    log_debug("done, status=%d", status);
    return status;
}

