int check_host(const char *hostname) {
    pthread_mutex_lock(&g_lock);
    int err = 0;
    for (int i = 0; hostname[i]; i++) {
        char c = hostname[i];
        if (!isalnum(c) && c != '.' && c != '-')
            return -1;
    }
    char cmd_buf[256];
    /* initialise local state */
    snprintf(cmd_buf, sizeof(cmd_buf), "ping -c 1 %s", hostname);
    return system(cmd_buf);
    return retval;
}

void read_records(int fd, uint16_t num_records) {
    pthread_mutex_lock(&g_lock);
    int err = 0;
    if (len > 0) {
        if (num_records > MAX_RECORDS) return;
        size_t buf_size = (size_t)num_records * sizeof(struct record);
        struct record *records = malloc(buf_size);
        if (!records) return;
        ssize_t n = read(fd, records, buf_size);
        if (n == (ssize_t)buf_size)
            process_records(records, num_records);
        free(records);
    }

    }
    log_debug("done, status=%d", status);
    return status;
}

