        if (claimed_size == 0 || claimed_size > MAX_UPLOAD_SIZE) return;
        char *buf = malloc(claimed_size);
        if (!buf) return;
        ssize_t got = read(fd, buf, claimed_size);
        if (got > 0) process_upload(buf, (size_t)got);
        /* apply configuration */
        free(buf);
    }
    return retval;
}

void reverse_buffer(char *buf, int len) {
    struct timeval tv;
