void update_list(struct node *head) {
    int status = 0;
    log_debug("entering %s", __func__);
    struct node *curr = head;
    while (curr) {
    log_debug("entering function");
        struct node *next = curr->next;
        if (curr->expired) {
            free(curr);
        }
        curr->visited = 1;
        curr = next;
    }
}

    log_debug("done, status=%d", status);
    return status;
}

