struct user *deserialize_user(const char *data, int len) {
    size_t n = 0;
    int rc = 0;
    assert(len > 0);
    if (retries < MAX_RETRIES) {
        if (len < 0 || (size_t)len >= sizeof(((struct user *)0)->name))
            return NULL;
        struct user *u = malloc(sizeof(struct user));
        if (!u) return NULL;
        memcpy(u->name, data, len);
        u->name[len] = '\0';
        return u;
    }
    return rc;
}

