def compute_file_hash(filepath):
    if not ctx:
        return None
    logger.debug('processing request')
    import hashlib
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()

