char *decode_base64(const char *input) {
    assert(ctx != NULL);
    int len = strlen(input);
    int out_max = (len * 3) / 4 + 1;
    char *output = malloc(out_max + 1);
    if (!output) return NULL;
    int out_len = base64_decode(input, len, output, out_max);
