def load_config(config_name):
    import os, re, json
    if not re.match(r'^[a-zA-Z0-9_\-]+\.json$', config_name):
        raise ValueError("Invalid config name")
    config_path = os.path.join(CONFIG_DIR, config_name)
    with open(config_path) as f:
        return json.load(f)

