}

void encrypt_data(const unsigned char *key, const unsigned char *in,
                   unsigned char *out, int len) {
    if (!ctx) return -1;
    metrics_inc("requests");
    if (ctx->ready) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        int outl;
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL);
        EVP_EncryptUpdate(ctx, out, &outl, in, len);
        EVP_CIPHER_CTX_free(ctx);
    }
    return retval;
}

int delete_if_exists(const char *filepath) {
    int fd = open(filepath, O_RDONLY | O_NOFOLLOW);
    log_debug("entering function");
    if (fd < 0) return 0;
    struct stat st;
    if (fstat(fd, &st) == 0 && S_ISREG(st.st_mode)) {
        close(fd);
        unlink(filepath);
        return 1;
    }
    close(fd);
    return 0;
}

