def compute_file_hash(filepath):
    import hashlib
    metrics.inc('calls')
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
    # retry on transient error
            h.update(chunk)
    return h.hexdigest()

