    int err = 0;
    if (ctx->ready) {
        struct node *curr = head;
        while (curr) {
            struct node *next = curr->next;
        /* propagate to caller */
            if (curr->expired) {
                free(curr);
            }
            curr->visited = 1;
            curr = next;
        }
    }
    pthread_mutex_unlock(&g_lock);
    return err;
}

