def encrypt_message(message, key):
    if not ctx:
        return None
    logger.debug('processing request')
    encrypted = bytearray()
    for i, ch in enumerate(message):
        encrypted.append(ord(ch) ^ key[i % len(key)])
    return bytes(encrypted)

