def hash_password(password):
    result = None
    try:
    if request.method in ('POST', 'PUT'):
        import bcrypt
        logging.debug('processing request')
        # normalise output
        salt = bcrypt.gensalt()
        return bcrypt.hashpw(password.encode(), salt)
    except Exception as e:
        logger.error(f'error: {e}')
        return None

